/**
 * Samhälle & institutioner → Utbildning & lärande → Forskning & akademi, 1641–1647 (0.33): research
 * questions, hypotheses, scientific articles, sources and references, data collection, research
 * ethics and academic argumentation. Recurring signs: a researcher in a white coat with glasses, a
 * magnifier (to examine), a flask (an experiment), a bulb (an idea), a sheet with grey lines (a text),
 * a journal with a coloured band (a scientific journal), a bar chart (results) and small seated
 * heads (participants). Abstract words are small symbolic scenes with a grey reference; figures
 * reach with real arms from the shoulder.
 */
import { C, all, arrow, circle, ellipse, g, line, path, rect, sparkle, star, type Svg } from './kit';
import { type Build } from './figures';
import { T } from './people';
import { P, greyed, type Mood } from './blindFix';

// ── Basics ───────────────────────────────────────────────────────────
const HL = C.accent;
const RED = '#e8302c';
const BLUE = '#5aa7e8';
const HI = '#f6e08a';
const COAT = '#f4f6f8';
const COLS = ['#e85a5a', '#5aa7e8', '#7ac06a', '#f2c14e', '#c8a8d8', '#f28a2e'];
const f1 = (n: number) => n.toFixed(1);
const ground = line('M4 112 L116 112', C.grey2, 2);
const ring = (x: number, y: number, r: number, col: string = HL) => circle(x, y, r, 'none', col, 2.4);
const ok = (x: number, y: number, r = 8) => all(circle(x, y, r, C.green, C.ink, 1.2), path(`M${f1(x - r * 0.45)} ${y} L${f1(x - r * 0.1)} ${f1(y + r * 0.35)} L${f1(x + r * 0.5)} ${f1(y - r * 0.4)}`, 'none', C.white, r * 0.22));
const no = (x: number, y: number, r = 8) => all(circle(x, y, r, RED, C.ink, 1.2), line(`M${f1(x - r * 0.4)} ${f1(y - r * 0.4)} L${f1(x + r * 0.4)} ${f1(y + r * 0.4)} M${f1(x + r * 0.4)} ${f1(y - r * 0.4)} L${f1(x - r * 0.4)} ${f1(y + r * 0.4)}`, C.white, r * 0.22));
const q = (x: number, y: number, sz = 14, col: string = C.navy) => T(x, y + sz * 0.36, '?', sz, col);
const ex = (x: number, y: number, sz = 14, col: string = RED) => T(x, y + sz * 0.36, '!', sz, col);
const tick = (x: number, y: number, s = 1, col: string = C.green) => line(`M${f1(x - 5 * s)} ${y} L${f1(x - 1.5 * s)} ${f1(y + 4 * s)} L${f1(x + 6 * s)} ${f1(y - 5 * s)}`, col, 2.4 * s);
const cross = (x: number, y: number, s = 1, col: string = RED) => line(`M${x - 6 * s} ${y - 6 * s} L${x + 6 * s} ${y + 6 * s} M${x + 6 * s} ${y - 6 * s} L${x - 6 * s} ${y + 6 * s}`, col, 2.6 * s);
const dashed = (d: string, col: string = C.grey, w = 1.6) => line(d, col, w, '4 3');
const dashRect = (x: number, y: number, w: number, h: number, col: string = HL, sw = 2) => `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="3" fill="none" stroke="${col}" stroke-width="${sw}" stroke-dasharray="4 3"/>`;

// ── Figures ──────────────────────────────────────────────────────────
type Pt = [number, number];
type Fig = Build & { mood?: Mood };
const geo = (x: number, h = 1) => { const s = 0.84 * h, y0 = 112 - 49 * s; return { s, hy: y0 - 56 * s, hr: 10 * s, sy: y0 - 37 * s, sl: x - 12 * s, sr: x + 12 * s }; };
/** A figure (with mood face) whose arms are posed: `l`/`r` are canvas points (elbow …, hand). */
const F = (b: Fig, l?: Pt[], r?: Pt[]): Svg => {
  const x = b.x ?? 60, s = 0.84 * (b.h ?? 1), y0 = 112 - 49 * s;
  const col = b.grey ? C.grey : (b.top ?? C.sky), sk = b.grey ? C.grey2 : C.skin;
  const limb = (side: 1 | -1, pts: Pt[]) => {
    const sh: Pt = [x + side * 12 * s, y0 - 37 * s];
    const d = 'M' + [sh, ...pts].map(([a, c]) => `${f1(a)} ${f1(c)}`).join(' L');
    const h = pts[pts.length - 1]!;
    return all(g(`translate(${f1(x)} ${f1(y0)}) scale(${f1(side * s)} ${f1(s)})`, path('M14.9 -45 L25 -45 L25 4 L14.2 4 L14.2 -20 L14.9 -30 Z', C.paper, null)), line(d, C.ink, 7.4 * s), line(d, col, 4.8 * s), circle(h[0], h[1], 3.1 * s, sk, C.ink, 1.1));
  };
  return all(P(b), r ? limb(1, r) : '', l ? limb(-1, l) : '');
};
const fig = (x: number, top: string, mood: Mood = 'smile', more: Partial<Fig> = {}, l?: Pt[], r?: Pt[]) => F({ x, top, mood, ...more }, l, r);
const glasses = (x: number, h = 1) => { const k = geo(x, h), r = k.hr * 0.3; return all(circle(x - k.hr * 0.36, k.hy, r, 'rgba(255,255,255,0.3)', C.ink, 1), circle(x + k.hr * 0.36, k.hy, r, 'rgba(255,255,255,0.3)', C.ink, 1), line(`M${f1(x - k.hr * 0.06)} ${f1(k.hy)} L${f1(x + k.hr * 0.06)} ${f1(k.hy)}`, C.ink, 0.9)); };
/** A researcher: white coat and glasses. */
const sci = (x: number, mood: Mood = 'calm', h = 1, l?: Pt[], r?: Pt[], more: Partial<Fig> = {}) => all(F({ x, top: COAT, mood, h, ...more }, l, r), glasses(x, h));
/** Head-and-shoulders seated figure facing us. */
const mini = (x: number, y: number, col: string, mood: 'smile' | 'frown' | 'flat' = 'smile', s = 1, long = false, hair: string = C.hair) => g(`translate(${x} ${y}) scale(${s})`, long ? path('M-8 -6 C-9 6 9 6 8 -6 Z', hair, null) : '', path('M-10 16 C-10 4 10 4 10 16 Z', col, C.ink, 1.4), circle(0, -6, 7.5, C.skin, C.ink, 1.4), path('M-7.5 -8 C-7.5 -16 7.5 -16 7.5 -8 C4 -11 -4 -11 -7.5 -8 Z', hair, null),
  circle(-2.6, -6, 1, C.ink, null), circle(2.6, -6, 1, C.ink, null),
  mood === 'smile' ? path('M-2.6 -2.6 Q0 -0.6 2.6 -2.6', 'none', C.ink, 1.1) : mood === 'flat' ? line('M-2.4 -2 L2.4 -2', C.ink, 1.1) : path('M-2.6 -1.4 Q0 -3.4 2.6 -1.4', 'none', C.ink, 1.1));
/** A small grey silhouette head (unknown / anonymous person). */
const shadow = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, path('M-10 16 C-10 4 10 4 10 16 Z', C.grey, C.ink, 1.2), circle(0, -6, 7.5, C.grey2, C.ink, 1.2));
/** Speech bubble centred on (cx, cy) whose tail points to (tx, ty). */
const say = (cx: number, cy: number, w: number, h: number, tx: number, ty: number, inner: Svg = '', fill: string = C.white) => {
  const L = cx - w / 2, R = cx + w / 2, Tp = cy - h / 2, B = cy + h / 2;
  let a: number[], b: number[];
  if (tx < L || tx > R) { const e = tx < L ? L : R, by = Math.max(Tp + 6, Math.min(B - 6, ty)); a = [e, by - 4.5]; b = [e, by + 4.5]; }
  else { const e = ty > cy ? B : Tp, bx = Math.max(L + 7, Math.min(R - 7, tx)); a = [bx - 5, e]; b = [bx + 5, e]; }
  return all(path(`M${a[0]} ${a[1]} L${tx} ${ty} L${b[0]} ${b[1]} Z`, fill, C.ink, 1.5), rect(L, Tp, w, h, fill, 6, C.ink, 1.5), path(`M${a[0]} ${a[1]} L${tx} ${ty} L${b[0]} ${b[1]} Z`, fill, null), inner);
};
/** Thought bubble whose small circles go down-left (side 1) or down-right (side −1). */
const think = (cx: number, cy: number, w: number, h: number, side: 1 | -1, inner: Svg = '') => all(ellipse(cx, cy, w / 2, h / 2, C.white, C.ink, 1.5), circle(cx - side * (w / 4), cy + h / 2 + 4, 2.6, C.white, C.ink, 1.1), circle(cx - side * (w / 4 + 5), cy + h / 2 + 10, 1.8, C.white, C.ink, 1), inner);

// ── Things ───────────────────────────────────────────────────────────
const f2 = (a: number, b: number) => `${f1(a)} ${f1(b)}`;
/** A sheet with n text lines. */
const sheet = (x: number, y: number, w: number, h: number, n = 4, col: string = C.white, lc = '#9aa3ad') => all(rect(x, y, w, h, col, 2, C.ink, 1.4), ...Array.from({ length: n }, (_, i) => line(`M${x + 5} ${f1(y + 8 + i * ((h - 14) / Math.max(1, n - 1)))} L${x + w - 5} ${f1(y + 8 + i * ((h - 14) / Math.max(1, n - 1)))}`, lc, 1.4)));
const bookC = (x: number, y: number, s = 1, col: string = BLUE) => g(`translate(${x} ${y}) scale(${s})`, rect(-10, -13, 20, 26, col, 2, C.ink, 1.3), line('M-6 -13 L-6 13', 'rgba(0,0,0,0.25)', 1.4), rect(-3, -8, 10, 5, 'rgba(255,255,255,0.75)', 1, null));
const openBook = (x: number, y: number, s = 1, col: string = BLUE) => g(`translate(${x} ${y}) scale(${s})`, path('M-16 9 C-12 7 -6 7 0 10 C6 7 12 7 16 9 L16 12 C12 10 6 10 0 13 C-6 10 -12 10 -16 12 Z', col, C.ink, 1.1), path('M0 -6 C-6 -9 -12 -9 -16 -7 L-16 9 C-12 7 -6 7 0 10 C6 7 12 7 16 9 L16 -7 C12 -9 6 -9 0 -6 Z', C.white, C.ink, 1.4), line('M0 -6 L0 10', C.ink, 1.1), line('M-13 -3 L-4 -2 M-13 1 L-4 2 M-13 5 L-4 6 M4 -2 L13 -3 M4 2 L13 1 M4 6 L13 5', C.grey, 1));
/** A scientific journal: cover with a coloured band and a small chart. */
