const shield = (x: number, y: number, s = 1, col: string = C.navy) => g(`translate(${x} ${y}) scale(${s})`, path('M0 -16 L14 -11 C14 4 8 12 0 17 C-8 12 -14 4 -14 -11 Z', col, C.ink, 1.6));
const coin = (x: number, y: number, r = 5) => all(circle(x, y, r, C.gold, C.ink, 1.2), circle(x, y, r * 0.55, 'none', '#b88a20', 1));
const pill = (x: number, y: number, rot = 30) => g(`translate(${x} ${y}) rotate(${rot})`, rect(-6, -3, 12, 6, C.white, 3, C.ink, 1.1), rect(0, -3, 6, 6, RED, 3, null), rect(-6, -3, 12, 6, 'none', 3, C.ink, 1.1));
const tree = (x: number, base: number, s = 1) => g(`translate(${x} ${base}) scale(${s})`, rect(-2, -14, 4, 14, C.brown, 1, C.ink, 1), circle(0, -20, 10, '#6fae5a', C.ink, 1.3));
const quote = (x: number, y: number, s = 1, col: string = C.navy) => T(x, y, '”', 26 * s, col, 900);
const stamp = (x: number, y: number, s = 1, col: string = C.green) => g(`translate(${x} ${y}) rotate(-12) scale(${s})`, circle(0, 0, 10, 'rgba(255,255,255,0.6)', col, 2.2), tick(0, 0, 0.8, col));
const mouse = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, path('M8 2 C14 2 16 -4 20 -2', 'none', '#e0a0b0', 1.4), ellipse(0, 0, 9, 6, C.white, C.ink, 1.3), circle(-8, -3, 4.6, C.white, C.ink, 1.3), circle(-9, -8, 2.6, '#f6c9d4', C.ink, 1), circle(-10, -3, 0.8, C.ink, null));
const cage = (x: number, y: number, w: number, h: number) => all(rect(x, y, w, h, 'none', 2, C.grey, 1.4), ...Array.from({ length: Math.floor(w / 6) }, (_, i) => line(`M${x + 6 + i * 6} ${y} L${x + 6 + i * 6} ${y + h}`, C.grey, 1)), rect(x - 2, y + h - 3, w + 4, 4, C.dark, 1, C.ink, 1));
const idCard = (x: number, y: number, s = 1, face: Svg = '') => g(`translate(${x} ${y}) scale(${s})`, rect(-18, -12, 36, 24, C.white, 3, C.ink, 1.4), rect(-15, -9, 12, 16, '#e6eef5', 1, C.ink, 0.9), face, line('M1 -6 L14 -6 M1 -1 L14 -1 M1 4 L10 4', '#9aa3ad', 1.4));
const puzzle = (x: number, y: number, s = 1, col: string = BLUE, stroke: string = C.ink) => g(`translate(${x} ${y}) scale(${s})`, path('M-10 -10 L-3 -10 C-3 -15 3 -15 3 -10 L10 -10 L10 -3 C15 -3 15 3 10 3 L10 10 L-10 10 Z', col, stroke, 1.4));
const scale2 = (x: number, y: number, tilt: number, lft: Svg, rgt: Svg) => all(line(`M${x} ${y} L${x} ${y + 40}`, C.brown, 3), path(`M${x - 12} ${y + 42} L${x + 12} ${y + 42} L${x + 8} ${y + 38} L${x - 8} ${y + 38} Z`, C.brown, C.ink, 1.2), g(`rotate(${tilt} ${x} ${y})`, line(`M${x - 30} ${y} L${x + 30} ${y}`, C.ink, 2.4), line(`M${x - 30} ${y} L${x - 36} ${y + 14} M${x - 30} ${y} L${x - 24} ${y + 14} M${x + 30} ${y} L${x + 24} ${y + 14} M${x + 30} ${y} L${x + 36} ${y + 14}`, C.ink, 1), path(`M${x - 38} ${y + 14} L${x - 22} ${y + 14} Q${x - 30} ${y + 20} ${x - 38} ${y + 14} Z`, C.gold, C.ink, 1.2), path(`M${x + 22} ${y + 14} L${x + 38} ${y + 14} Q${x + 30} ${y + 20} ${x + 22} ${y + 14} Z`, C.gold, C.ink, 1.2), g(`translate(${x - 30} ${y + 8}) rotate(${-tilt})`, lft), g(`translate(${x + 30} ${y + 8}) rotate(${-tilt})`, rgt)), circle(x, y, 2.6, C.gold, C.ink, 1));
/** A grid of small heads (a group of people). */
const crowd = (x: number, y: number, cols: number, rows: number, colour: (i: number) => string, dx = 13, dy = 15, s = 0.5) => all(...Array.from({ length: cols * rows }, (_, i) => mini(x + (i % cols) * dx, y + Math.floor(i / cols) * dy, colour(i), 'smile', s)));
/** Stepwise arrow chain of boxes with icons. */
const chain = (xs: number[], y: number, icons: Svg[], col: string = HL) => all(...xs.slice(0, -1).map((x, i) => arrow(x + 13, y, xs[i + 1]! - 13, y, col, 2.2)), ...xs.map((x, i) => all(rect(x - 12, y - 12, 24, 24, C.white, 4, C.ink, 1.4), icons[i] ?? '')));
/** A paper with highlighted block `hi` (0 = top block) of n blocks; heading bar on each block when `heads`. */
const blocks = (x: number, y: number, w: number, n: number, hi: number, heads = false) => { const bh = 22; return all(rect(x, y, w, n * bh + 8, C.white, 2, C.ink, 1.5), ...Array.from({ length: n }, (_, i) => { const by = y + 6 + i * bh, on = i === hi; return all(on ? rect(x + 3, by - 2, w - 6, bh - 1, HI, 2, null) : '', heads ? rect(x + 6, by + 1, w * 0.45, 4, on ? C.navy : C.grey, 1, null) : '', line(`M${x + 6} ${by + (heads ? 10 : 4)} L${x + w - 6} ${by + (heads ? 10 : 4)} M${x + 6} ${by + (heads ? 15 : 10)} L${x + w - 10} ${by + (heads ? 15 : 10)}`, on ? C.ink : '#b8bec5', 1.4), heads ? '' : line(`M${x + 6} ${by + 16} L${x + w - 14} ${by + 16}`, on ? C.ink : '#b8bec5', 1.4)); })); };

